// ============================================================
// FSMGuard Patch - Guard Insertion
// CWE: CWE-1245
// Parameter: privilege_check
// Strictness: strict
// ============================================================
// This patch enforces access control before entering ADMIN
// Added by FSMGuard Stage 08 based on RL agent decision




// Strict mode: Fallback to RESET with alert if insufficient privilege
always @(posedge clk) begin
    if (next_state_logic == ADMIN) begin
        if (privilege_level == 2'b11) begin
            next_state = ADMIN;
        end else begin
            alert_signal = 1'b1;
            next_state = RESET;
        end
    end
end




// ============================================================
// End FSMGuard Patch
// ============================================================
